/*
 * In case of ON CONFLICT DO NOTHING, do nothing. However,
 * verify that the tuple is visible to the executor's MVCC
 * snapshot at higher isolation levels.
 *
 * Using ExecGetReturningSlot() to store the tuple for the
 * recheck isn't that pretty, but we can't trivially use
 * the input slot, because it might not be of a compatible
 * type. As there's no conflicting usage of
 * ExecGetReturningSlot() in the DO NOTHING case...
 */
Assert(onconflict == ONCONFLICT_NOTHING);
ExecCheckTIDVisible(estate, resultRelInfo, &conflictTid,
					ExecGetReturningSlot(estate, resultRelInfo));
InstrCountTuples2(&mtstate->ps, 1);
return NULL;

/*
 * At this point we have either a conflict or a potential conflict.
 *
 * If an in-progress transaction is affecting the visibility of this
 * tuple, we need to wait for it to complete and then recheck (unless
 * the caller requested not to).  For simplicity we do rechecking by
 * just restarting the whole scan --- this case probably doesn't
 * happen often enough to be worth trying harder, and anyway we don't
 * want to hold any index internal locks while waiting.
 */
xwait = TransactionIdIsValid(DirtySnapshot.xmin) ?
	DirtySnapshot.xmin : DirtySnapshot.xmax;

if (TransactionIdIsValid(xwait) &&
	(waitMode == CEOUC_WAIT ||
	 (waitMode == CEOUC_LIVELOCK_PREVENTING_WAIT &&
	  DirtySnapshot.speculativeToken &&
	  TransactionIdPrecedes(GetCurrentTransactionId(), xwait))))
{
	reason_wait = indexInfo->ii_ExclusionOps ?
		XLTW_RecheckExclusionConstr : XLTW_InsertIndex;
	index_endscan(index_scan);
	if (DirtySnapshot.speculativeToken)
		SpeculativeInsertionWait(DirtySnapshot.xmin,
								 DirtySnapshot.speculativeToken);
	else
		XactLockTableWait(xwait, heap,
						  &existing_slot->tts_tid, reason_wait);
	goto retry;

/*
 * Before we start insertion proper, acquire our "speculative
 * insertion lock".  Others can use that to wait for us to decide
 * if we're going to go ahead with the insertion, instead of
 * waiting for the whole transaction to complete.
 */
specToken = SpeculativeInsertionLockAcquire(GetCurrentTransactionId());

/* insert the tuple, with the speculative token */
table_tuple_insert_speculative(resultRelationDesc, slot,
							   estate->es_output_cid,
							   0,
							   NULL,
							   specToken);

/* insert index entries for tuple */
recheckIndexes = ExecInsertIndexTuples(resultRelInfo,
									   slot, estate, false, true,
									   &specConflict,
									   arbiterIndexes,
									   false);

/* adjust the tuple's state accordingly */
table_tuple_complete_speculative(resultRelationDesc, slot,
								 specToken, !specConflict);

/*
 * Wake up anyone waiting for our decision.  They will re-check
 * the tuple, see that it's no longer speculative, and wait on our
 * XID as if this was a regularly inserted tuple all along.  Or if
 * we killed the tuple, they will see it's dead, and proceed as if
 * the tuple never existed.
 */
SpeculativeInsertionLockRelease(GetCurrentTransactionId());

/*
 * If there was a conflict, start from the beginning.  We'll do
 * the pre-check again, which will now find the conflicting tuple
 * (unless it aborts before we get there).
 */
if (specConflict)
{
	list_free(recheckIndexes);
	goto vlock;
}

/* When specific arbiter indexes requested, only examine them */
if (arbiterIndexes != NIL &&
	!list_member_oid(arbiterIndexes,
					 indexRelation->rd_index->indexrelid))
	continue;

if (!indexRelation->rd_index->indimmediate)
	ereport(ERROR,
			(errcode(ERRCODE_OBJECT_NOT_IN_PREREQUISITE_STATE),
			 errmsg("ON CONFLICT does not support deferrable unique constraints/exclusion constraints as arbiters"),
			 errtableconstraint(heapRelation,
								RelationGetRelationName(indexRelation))));

if (checkingunique)
{
	if (!itup_key->anynullkeys)
	{
		/* No (heapkeyspace) scantid until uniqueness established */
		itup_key->scantid = NULL;
	}
	else
	{
		/*
		 * Scan key for new tuple contains NULL key values.  Bypass
		 * checkingunique steps.  They are unnecessary because core code
		 * considers NULL unequal to every value, including NULL.
		 *
		 * This optimization avoids O(N^2) behavior within the
		 * _bt_findinsertloc() heapkeyspace path when a unique index has a
		 * large number of "duplicates" with NULL key values.
		 */
		checkingunique = false;
		/* Tuple is unique in the sense that core code cares about */
		Assert(checkUnique != UNIQUE_CHECK_EXISTING);
		is_unique = true;

satisfiesConstraint =
	check_exclusion_or_unique_constraint(heapRelation, indexRelation,
										 indexInfo, tupleid,
										 values, isnull, estate, false,
										 CEOUC_WAIT, true,
										 conflictTid);
if (!satisfiesConstraint)
	return false;

 * For a speculative insertion (used by INSERT ... ON CONFLICT), do
 * the same as for a deferrable unique index.
 */
if (!indexRelation->rd_index->indisunique)
	checkUnique = UNIQUE_CHECK_NO;
else if (applyNoDupErr)
	checkUnique = UNIQUE_CHECK_PARTIAL;
else if (indexRelation->rd_index->indimmediate)
	checkUnique = UNIQUE_CHECK_YES;
else
	checkUnique = UNIQUE_CHECK_PARTIAL;

if ((checkUnique == UNIQUE_CHECK_PARTIAL ||
	 indexInfo->ii_ExclusionOps != NULL) &&
	!satisfiesConstraint)
{
	/*
	 * The tuple potentially violates the uniqueness or exclusion
	 * constraint, so make a note of the index so that we can re-check
	 * it later.  Speculative inserters are told if there was a
	 * speculative conflict, since that always requires a restart.
	 */
	result = lappend_oid(result, RelationGetRelid(indexRelation));
	if (indexRelation->rd_index->indimmediate && specConflict)
		*specConflict = true;

if (checkUnique == UNIQUE_CHECK_PARTIAL)
{
	if (nbuf != InvalidBuffer)
		_bt_relbuf(rel, nbuf);
	*is_unique = false;
	return InvalidTransactionId;
}

/*
 * If this tuple is being updated by other transaction
 * then we have to wait for its commit/abort.
 */
xwait = (TransactionIdIsValid(SnapshotDirty.xmin)) ?
	SnapshotDirty.xmin : SnapshotDirty.xmax;

if (TransactionIdIsValid(xwait))
{
	if (nbuf != InvalidBuffer)
		_bt_relbuf(rel, nbuf);
	/* Tell _bt_doinsert to wait... */
	*speculativeToken = SnapshotDirty.speculativeToken;
	/* Caller releases lock on buf immediately */
	insertstate->bounds_valid = false;
	return xwait;
}

heapam_tuple_insert_speculative(Relation relation, TupleTableSlot *slot,
								CommandId cid, int options,
								BulkInsertState bistate, uint32 specToken)
{
	bool		shouldFree = true;
	HeapTuple	tuple = ExecFetchSlotHeapTuple(slot, true, &shouldFree);

	/* Update the tuple with table oid */
	slot->tts_tableOid = RelationGetRelid(relation);
	tuple->t_tableOid = slot->tts_tableOid;

	HeapTupleHeaderSetSpeculativeToken(tuple->t_data, specToken);
	options |= HEAP_INSERT_SPECULATIVE;

	/* Perform the insertion, and copy the resulting ItemPointer */
	heap_insert(relation, tuple, cid, options, bistate);
	ItemPointerCopy(&tuple->t_self, &slot->tts_tid);

	if (shouldFree)
		pfree(tuple);
}

static void
heapam_tuple_complete_speculative(Relation relation, TupleTableSlot *slot,
								  uint32 specToken, bool succeeded)
{
	bool		shouldFree = true;
	HeapTuple	tuple = ExecFetchSlotHeapTuple(slot, true, &shouldFree);

	/* adjust the tuple's state accordingly */
	if (succeeded)
		heap_finish_speculative(relation, &slot->tts_tid);
	else
		heap_abort_speculative(relation, &slot->tts_tid);

tup->t_data->t_infomask &= ~(HEAP_XACT_MASK);
tup->t_data->t_infomask2 &= ~(HEAP2_XACT_MASK);
tup->t_data->t_infomask |= HEAP_XMAX_INVALID;
HeapTupleHeaderSetXmin(tup->t_data, xid);
if (options & HEAP_INSERT_FROZEN)
	HeapTupleHeaderSetXminFrozen(tup->t_data);

HeapTupleHeaderSetCmin(tup->t_data, cid);
HeapTupleHeaderSetXmax(tup->t_data, 0); /* for cleanliness */
tup->t_tableOid = RelationGetRelid(relation);

/*
 * Prepare the new tuple with the appropriate initial values of Xmin and
 * Xmax, as well as initial infomask bits as computed above.
 */
newtup->t_data->t_infomask &= ~(HEAP_XACT_MASK);
newtup->t_data->t_infomask2 &= ~(HEAP2_XACT_MASK);
HeapTupleHeaderSetXmin(newtup->t_data, xid);
HeapTupleHeaderSetCmin(newtup->t_data, cid);
newtup->t_data->t_infomask |= HEAP_UPDATED | infomask_new_tuple;
newtup->t_data->t_infomask2 |= infomask2_new_tuple;
HeapTupleHeaderSetXmax(newtup->t_data, xmax_new_tuple);

if (!is_parallel_worker)
{
	/*
	 * We need to mark our XIDs as committed in pg_xact.  This is where we
	 * durably commit.
	 */
	latestXid = RecordTransactionCommit();
}
else
{
	/*
	 * We must not mark our XID committed; the parallel leader is
	 * responsible for that.
	 */
	latestXid = InvalidTransactionId;

	/*
	 * Make sure the leader will know about any WAL we wrote before it
	 * commits.
	 */
	ParallelWorkerReportLastRecEnd(XactLastRecEnd);
}

TRACE_POSTGRESQL_TRANSACTION_COMMIT(MyProc->vxid.lxid);

/*
 * Let others know about no transaction in progress by me. Note that this
 * must be done _before_ releasing locks we hold and _after_
 * RecordTransactionCommit.
 */
ProcArrayEndTransaction(MyProc, latestXid);

	else if (XidInMVCCSnapshot(HeapTupleHeaderGetRawXmin(tuple), snapshot))
		return false;
	else if (TransactionIdDidCommit(HeapTupleHeaderGetRawXmin(tuple)))
		SetHintBits(tuple, buffer, HEAP_XMIN_COMMITTED,
					HeapTupleHeaderGetRawXmin(tuple));
	else
	{
		/* it must have aborted or crashed */
		SetHintBits(tuple, buffer, HEAP_XMIN_INVALID,
					InvalidTransactionId);
		return false;
	}
}
else
{
	/* xmin is committed, but maybe not according to our snapshot */
	if (!HeapTupleHeaderXminFrozen(tuple) &&
		XidInMVCCSnapshot(HeapTupleHeaderGetRawXmin(tuple), snapshot))
		return false;		/* treat as still in progress */
}

/* by here, the inserting transaction has committed */

if (tuple->t_infomask & HEAP_XMAX_INVALID)	/* xid invalid or aborted */
	return true;

if (XidInMVCCSnapshot(HeapTupleHeaderGetRawXmax(tuple), snapshot))
	return true;

if (!TransactionIdDidCommit(HeapTupleHeaderGetRawXmax(tuple)))
{
	/* it must have aborted or crashed */
	SetHintBits(tuple, buffer, HEAP_XMAX_INVALID,
				InvalidTransactionId);
	return true;

ExecCheckTIDVisible(EState *estate,
					ResultRelInfo *relinfo,
					ItemPointer tid,
					TupleTableSlot *tempSlot)
{
	Relation	rel = relinfo->ri_RelationDesc;

	/* Redundantly check isolation level */
	if (!IsolationUsesXactSnapshot())
		return;

	if (!table_tuple_fetch_row_version(rel, tid, SnapshotAny, tempSlot))
		elog(ERROR, "failed to fetch conflicting tuple for ON CONFLICT");
	ExecCheckTupleVisible(estate, rel, tempSlot);
